#!/bin/zsh
# 按 11-13 定下的新设计语言（暖灰 + 玫瑰红），出「素材库 + 项目」和首页新模块的图。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "当前目录的 ref_current.jpg 是这款 macOS 应用「豆仓」现在已经定稿的录音页截图。请先仔细看这张图，然后使用内置的 image_gen 工具（把它一起传入，设计语言必须完全一致：暖灰底、白色圆角卡片、玫瑰红 #F43F5E 强调色、深色选中的小筛选块、左侧品牌卡和圆角渐变录音键）生成一张 16:10 横向的高保真 UI 设计稿（正视图、不要透视）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="界面文字全部是简体中文，像苹方，清晰可读、没有乱码。不要蓝色、紫色。保持简洁，不要加多余的装饰。"
gen ui_materials "【素材库页 + 项目】左侧侧栏：品牌卡、玫瑰红「开始录音」、导航四项「总览」「录音 20」「素材 6」「知识库」（「素材」是选中状态）；导航下面一个小标题「项目」，右边一个小的加号按钮，下面三个项目，每个是文件夹小图标 + 名字 + 灰色数字：「新品发布 5」「客户访谈 3」「选题库 8」；侧栏底部是设备卡。中间一栏是素材列表：标题「素材库」和「6 条」，标题下面是一个粘贴框（暖灰底圆角，左边链接小图标，占位文字「粘贴视频链接或分享口令」，右边一个玫瑰红小按钮「导入」），再下面是搜索框和一排筛选「全部 / 抖音 / B 站 / YouTube」（全部是深色选中），列表是卡片：左边一个播放三角的小方块，标题如「三分钟讲清楚复利」，下面一行小字「抖音 · @某某 · 3:12」，右边一个浅灰小块写项目名「选题库」；其中一张卡片是选中状态（玫瑰红描边）。右边一栏是这条素材的详情：顶部「抖音 · @某某」标签和日期、右上角一排图标按钮，标题，右侧「纪要 / 文字稿 / 改写」页签，下面是「摘要」卡片和「拆解写法」卡片（钩子、结构、金句三小段）。$S" &
gen ui_select_projects "【录音页的多选和移到项目】和参考图同样的三栏布局。中间录音列表处在多选状态：列表头右边有一个「完成」文字按钮，每张卡片左上角是一个圆形勾选框，其中三张被勾上（玫瑰红实心圆加白勾、卡片玫瑰红描边）；列表底部浮着一条白色圆角操作条：左边「已选 3 条」，右边三个按钮「移到项目」（带下拉小箭头）、「星标」、「删除」（玫瑰红字）。「移到项目」的下拉菜单是展开的，macOS 原生菜单样式：「新品发布」「客户访谈」「选题库」、分隔线、「新建项目…」「移出项目」。左侧侧栏导航下面有「项目」小标题和三个项目。右边详情栏画一条录音的纪要即可。$S" &
gen ui_home_links "【总览页】左侧侧栏同上（导航四项，「总览」选中，下面项目列表）。右侧主区域：左上角是珍珠白小仓鼠吉祥物（脖子挂耳机）和大字「下午好」，下面一行灰字「有 3 件事等你处理」。下面左右两栏卡片：左栏「接下来要做的」三条带圆形勾选框的待办；右栏「最近的录音」三张小卡。再下面一整行宽卡片「从链接导入」：卡片标题左边一个玫瑰红链接图标，右边一个灰色文字按钮「查看全部素材」；卡片里先是一个粘贴框（暖灰底圆角，占位文字「粘贴视频链接或分享口令，下载声音、转成文字稿」，右边玫瑰红「导入」按钮），下面一行小灰字「支持抖音、B 站、YouTube、TikTok、X 等公开内容」，再下面是三条最近导入的素材，横排三张小卡：播放三角小方块、标题、「B 站 · 4:05」。$S" &
wait
